-- Presupuesto 2026, volcado desde la hoja Previsión de Presupuesto_2026.xlsx
-- Generado el 2026-08-20.
--
-- CONVENIO DE SIGNOS: el mismo que en movimientos.
--   ingreso                       -> importe positivo
--   gasto / ahorro / inversion    -> importe negativo
-- Sin esto, v_ppto_vs_real restaria un positivo de un negativo y la
-- desviacion saldria del doble del importe.
--
-- Solo se vuelcan los importes distintos de cero.
-- Idempotente: reejecutarlo sobrescribe los importes, no duplica filas.

SET SESSION sql_mode = CONCAT(@@sql_mode, ',STRICT_ALL_TABLES');

ON DUPLICATE KEY UPDATE importe = VALUES(importe);

-- Comprobacion
SELECT c.tipo,
       COUNT(*)                AS lineas,
       ROUND(SUM(p.importe),2) AS suma_anual
  FROM presupuesto p JOIN categorias c ON c.id = p.categoria_id
 WHERE p.anio = 2026
 GROUP BY c.tipo WITH ROLLUP;